import java.util.*;

public class Main {
    List<Integer> removeZeroSumSublists(List<Integer> values) {
        List<Integer> result = new ArrayList<>(values);
        boolean changed = true;
        while (changed) {                                                             // keep repeating until no zero-sum span remains
            changed = false;
            outer:
            for (int i = 0; i < result.size(); i++) {
                int total = 0;
                for (int j = i; j < result.size(); j++) {
                    total += result.get(j);
                    if (total == 0) {                                                     // found a zero-sum span from i to j
                        result.subList(i, j + 1).clear();                                    // remove that entire span
                        changed = true;
                        break outer;
                    }
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = new ArrayList<>(Arrays.asList(1, 2, 3, -3, 4));
        System.out.println(solution.removeZeroSumSublists(values));
    }
}

