#include <bits/stdc++.h>
using namespace std;

vector<int> removeZeroSumSublists(vector<int>& values) {
    vector<int> result = values;
    bool changed = true;
    while (changed) {                                                                 // keep repeating until no zero-sum span remains
        changed = false;
        for (int i = 0; i < (int)result.size() && !changed; i++) {
            int total = 0;
            for (int j = i; j < (int)result.size(); j++) {
                total += result[j];
                if (total == 0) {                                                         // found a zero-sum span from i to j
                    result.erase(result.begin() + i, result.begin() + j + 1);                // remove that entire span
                    changed = true;
                    break;
                }
            }
        }
    }
    return result;
}

int main() {
    vector<int> values = {1, 2, 3, -3, 4};
    vector<int> result = removeZeroSumSublists(values);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

