import java.util.*;

public class Main {
    ListNode removeZeroSumSublists(ListNode head) {
        ListNode dummy = new ListNode(0, head);
        Map<Integer, ListNode> seen = new HashMap<>();
        seen.put(0, dummy);                                                            // prefix sum 0 corresponds to "before the list starts"

        int total = 0;
        for (ListNode node = dummy.next; node != null; node = node.next) {
            total += node.val;
            seen.put(total, node);                                                        // always keep the LAST node seen with this exact prefix sum
        }

        total = 0;
        for (ListNode node = dummy; node != null; node = node.next) {
            total += node.val;
            node.next = seen.get(total).next;                                             // jump directly past everything summing to zero in between
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(-3, new ListNode(-2)))));
        ListNode result = solution.removeZeroSumSublists(head);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

