#include <bits/stdc++.h>
using namespace std;

ListNode* removeZeroSumSublists(ListNode* head) {
    ListNode dummy(0, head);
    unordered_map<int, ListNode*> seen;
    seen[0] = &dummy;                                                                 // prefix sum 0 corresponds to "before the list starts"

    int total = 0;
    for (ListNode* node = dummy.next; node; node = node->next) {
        total += node->val;
        seen[total] = node;                                                              // always keep the LAST node seen with this exact prefix sum
    }

    total = 0;
    for (ListNode* node = &dummy; node; node = node->next) {
        total += node->val;
        node->next = seen[total]->next;                                                  // jump directly past everything summing to zero in between
    }
    return dummy.next;
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(-3, new ListNode(-2)))));
    ListNode* result = removeZeroSumSublists(head);
    while (result) { cout << result->val << " "; result = result->next; }
    cout << endl;
    return 0;
}
